  \label{tab:s3_llm}
  \begin{tabular}{lccc}
    \toprule
    \textbf{Depth} & \textbf{GPT-5.5} & \textbf{Claude Opus 4.6} & \textbf{OBD-LightGBM} \\
    \midrule
    0 (human)    & 0.77  & 0.69  & --- \\
    1            & 0.19  & 0.21  & --- \\
    2            & 0.38  & 0.28  & --- \\
    3            & 0.24  & 0.101 & --- \\
    4            & 0.08  & 0.37  & --- \\
    \midrule
    5-class acc  & 0.332 & 0.331 & 0.386 \\
    Binary acc   & 0.878 & 0.882 & --- \\
    \bottomrule
  \end{tabular}
\end{table}

